import{readSettlementLibrary}from'./settlement-library.js';import{attachDepartmentStore,fitDepartmentDoors}from'./department-store.js';
import {linkInteriorToBuilding} from './interior-model.js';
import{uid}from'./model.js';
import{buildingAxes,fitBuildingRect,planBuilding,drawBuilding,buildingObject,makeInterior,plantTree,paintBuildingRow}from'./builder-model.js';
export function builderWorkshop(api,builtin){
 const $=s=>document.querySelector(s),esc=api.esc,state={tab:'buildings',query:'',region:'all',kind:'all',templateId:builtin.buildings?.[0]?.id,treeIds:[],radius:1,spacing:2,erase:false,offerInterior:false};
 const buildings=()=>api.library.list('buildingTemplates',api.project()),buildingItems=()=>api.smart().prefabs().filter(p=>p.category?.startsWith('Buildings')||p.buildingTemplateId),trees=()=>api.smart().prefabs().filter(p=>p.brushKind==='tree'),interiors=()=>builtin.interiorPlans||[],sets=()=>builtin.furnishingSets||[];
 const thumb=(a,name)=>`<img class="smart-thumb" src="${esc(a.data||a.src)}" alt="${esc(name)}">`;
 const recipeFor=t=>interiors().find(i=>i.id===t.interiorPlanId)||interiors().find(i=>i.kind===t.kind&&i.region===t.region)||interiors().find(i=>i.kind===t.kind)||interiors().find(i=>i.kind==='house');
 function open(tab=state.tab){state.tab=tab;api.modal('Build your world',`<div class="smart-tabs builder-tabs">${[['buildings','Buildings'],['expand','Resize a building'],['doors','Doors & portals'],['sets','Furnishing sets'],['trees','Tree brush'],['rom','Game editing']].map(([id,name])=>`<button type="button" data-builder-tab="${id}" class="${id===tab?'active':''}">${name}</button>`).join('')}</div><div id="builderContent"></div>`);document.querySelectorAll('[data-builder-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.builderTab;render();});render();}
 function render(){document.querySelectorAll('[data-builder-tab]').forEach(b=>b.classList.toggle('active',b.dataset.builderTab===state.tab));const content=$('#builderContent');
 if(state.tab==='buildings'||state.tab==='expand'){
  const expand=state.tab==='expand',items=expand?buildings().filter(t=>{const a=buildingAxes(t);return a.x||a.y;}):buildingItems();
  content.innerHTML=`<p>${expand?'Drag to size a building. Only designs with safe repeating sections appear here. Fixed axes keep their original size automatically.':'Tap Place, then tap the map. Every building appears at its original pixel size, including originals of the resizable designs.'}</p><div class="builder-filters"><input id="buildingSearch" type="search" placeholder="Centre, Mart, Gym, house, Indigo…" value="${esc(state.query)}"><select id="buildingRegion" aria-label="Region"><option value="all">All regions / styles</option>${[...new Set(items.map(b=>b.region||'Ekat'))].map(r=>`<option ${state.region===r?'selected':''}>${esc(r)}</option>`).join('')}</select><select id="buildingKind" aria-label="Building type"><option value="all">All building types</option>${[...new Set(items.map(b=>b.kind||'building'))].map(k=>`<option ${state.kind===k?'selected':''}>${esc(k)}</option>`).join('')}</select></div>${!expand?`<label class="check"><input id="buildingOfferInside" type="checkbox" ${state.offerInterior?'checked':''}> Offer a linked interior after placing a building</label>`:''}<div id="buildingCards" class="smart-cards"></div>`;
  const cards=()=>{$('#buildingCards').innerHTML=items.filter(t=>(state.region==='all'||(t.region||'Ekat')===state.region)&&(state.kind==='all'||(t.kind||'building')===state.kind)&&(t.name+' '+t.kind+' '+t.region+' '+(t.tags||'')).toLowerCase().includes(state.query.toLowerCase())).map(t=>{const axes=expand&&buildingAxes(t);return`<article class="smart-card">${thumb(api.asset(t.assetId),t.name)}<strong>${esc(t.name)}</strong><small>${esc(t.region||'Ekat')} · ${t.w} × ${t.h} tiles${expand?' · '+(axes.x&&axes.y?'resize width & height':axes.x?'resize width · fixed height':'fixed width · resize height'):''}</small><button type="button" ${expand?'data-build-template':'data-place-building'}="${esc(t.id)}">${expand?'Drag to size':'Place original'}</button></article>`;}).join('')||'<p>No buildings match these filters.</p>';document.querySelectorAll('[data-build-template]').forEach(b=>b.onclick=()=>{const t=buildings().find(t=>t.id===b.dataset.buildTemplate);state.templateId=t.id;api.change(()=>api.library.attach(api.project(),'buildingTemplates',t));api.mode('building');api.close();const a=buildingAxes(t);api.toast('Drag '+t.name+' · '+(a.x&&a.y?'width & height':a.x?'width only':'height only')+'.');});document.querySelectorAll('[data-place-building]').forEach(b=>b.onclick=()=>{const p=buildingItems().find(p=>p.id===b.dataset.placeBuilding);api.change(()=>api.library.attach(api.project(),'prefabs',p));api.prefab(p);api.close();});};if($('#buildingOfferInside'))$('#buildingOfferInside').onchange=e=>state.offerInterior=e.target.checked;$('#buildingSearch').oninput=e=>{state.query=e.target.value;cards();};$('#buildingRegion').onchange=e=>{state.region=e.target.value;cards();};$('#buildingKind').onchange=e=>{state.kind=e.target.value;cards();};cards();
 }else if(state.tab==='doors'){api.doors().open();return;
 }else if(state.tab==='sets'){
  content.innerHTML=`<p>Matched furnishings, floors and wallpaper. Individual objects remain editable and can be duplicated into My library.</p><div class="smart-cards">${sets().map(s=>{const p=api.smart().prefabs().find(p=>s.prefabIds.includes(p.id)),a=p&&api.asset(p.assetId);return`<article class="smart-card">${a?thumb(a,s.name):''}<strong>${esc(s.name)}</strong><small>${s.prefabIds.length} objects · ${esc(s.region||'Ekat')}</small><div class="smart-actions"><button type="button" data-furnish-set="${esc(s.id)}">Objects</button>${s.themeId?`<button type="button" data-set-wallpaper="${esc(s.id)}">Floor & wallpaper</button>`:''}</div></article>`;}).join('')}</div>`;document.querySelectorAll('[data-furnish-set]').forEach(b=>b.onclick=()=>api.smart().openSet(sets().find(s=>s.id===b.dataset.furnishSet)));document.querySelectorAll('[data-set-wallpaper]').forEach(b=>b.onclick=()=>{api.smart().state.roomId=sets().find(s=>s.id===b.dataset.setWallpaper).themeId;api.mode('room');api.close();api.toast('Drag a room to use this matching floor and wallpaper.');});
 }else if(state.tab==='trees'){
  if(!state.treeIds.length&&trees()[0])state.treeIds=[trees()[0].id];content.innerHTML=`<p>Drag to plant complete trees with overlapping foliage and solid trunks. Select several styles to mix them. Ground remains editable below the trees.</p><div class="field-row"><label>Brush radius<select id="treeRadius">${[1,2,3,4].map(n=>`<option value="${n}" ${state.radius===n?'selected':''}>${n} tile${n===1?'':'s'}</option>`).join('')}</select></label><label>Trunk spacing<select id="treeSpacing">${[1,2,3,4].map(n=>`<option value="${n}" ${state.spacing===n?'selected':''}>${n} tile${n===1?'':'s'}</option>`).join('')}</select></label></div><div class="smart-actions"><button id="paintTrees" type="button" class="primary">Paint trees</button><button id="eraseTrees" type="button">Erase painted trees</button></div><div class="smart-cards tree-cards">${trees().map(p=>`<label class="smart-card">${thumb(api.asset(p.assetId),p.name)}<span><input type="checkbox" data-tree-id="${esc(p.id)}" ${state.treeIds.includes(p.id)?'checked':''}> ${esc(p.name)}</span><small>${p.w} × ${p.h} · trunk collision / foreground leaves</small></label>`).join('')}</div>`;$('#treeRadius').onchange=e=>state.radius=+e.target.value;$('#treeSpacing').onchange=e=>state.spacing=+e.target.value;document.querySelectorAll('[data-tree-id]').forEach(b=>b.onchange=()=>{state.treeIds=[...document.querySelectorAll('[data-tree-id]:checked')].map(b=>b.dataset.treeId);});const begin=erase=>{state.buildingBrush=null;if(!erase&&!state.treeIds.length){api.toast('Choose at least one tree.');return;}state.erase=erase;for(const p of trees().filter(p=>state.treeIds.includes(p.id)))api.change(()=>api.library.attach(api.project(),'prefabs',p));api.mode('tree');api.close();api.toast(erase?'Drag across trunks to erase brush trees.':'Tree brush ready. Drag across the map.');};$('#paintTrees').onclick=()=>begin(false);$('#eraseTrees').onclick=()=>begin(true);
 }else{
  content.innerHTML=`<div class="callout"><b>Edits that play in the ROM</b><p>Walking rules, foreground overlap, map artwork, linked portals, dialogue, ordered event actions and gates are compiled into an edited GBA copy.</p></div><div class="smart-actions"><button id="builderGame" type="button" class="primary">Game workshop</button><button id="builderHM" type="button">HMs & jump ledges</button><button id="builderRules" type="button">Paint walking rules</button><button id="builderEvents" type="button">Manage events</button><button id="builderExport" type="button">Export edited ROM</button></div><p>Generated interiors become new maps when the opened ROM has a supported map-group accessor. Other hacks can use an existing map slot if adding a map bank is unsupported. The review screen shows what will be written and how the artwork fits the game’s palettes.</p><p class="hint-line">Game workshop adds native Pokémon, move, item, trainer, encounter and sprite editing for verified sources. Engine/code and music changes remain separate specialist tasks.</p>`;$('#builderGame').onclick=()=>api.game().open();$('#builderHM').onclick=()=>api.field().open();$('#builderRules').onclick=()=>api.world().open('movement');$('#builderEvents').onclick=()=>api.events().open();$('#builderExport').onclick=api.exportROM;
 }}
 async function construct(rect,existing=null){try{
  const template=buildings().find(t=>t.id===(existing?.building?.templateId||state.templateId));if(!template)throw Error('Choose a building template.');const map=api.map(),plan=planBuilding(template,fitBuildingRect(template,rect,map),map),image=await api.ensureImage(template.assetId),canvas=document.createElement('canvas');canvas.width=plan.w*16;canvas.height=plan.h*16;const extensions={};for(const axis of ['X','Y','XY'])if(template['extension'+axis+'AssetId'])extensions['extension'+axis]=await api.ensureImage(template['extension'+axis+'AssetId']);drawBuilding(canvas.getContext('2d'),image,template,plan,extensions);const storeLibrary=template.departmentFamily?await readSettlementLibrary():null;const recipe=recipeFor(template),themes=api.smart().rooms(),theme=themes.find(t=>t.id===recipe?.themeId)||themes[0];
  api.modal('Build '+template.name,`<img class="building-preview" src="${canvas.toDataURL('image/png')}" alt="Building at requested size"><p>${plan.w} × ${plan.h} tiles · entrance ${plan.x+plan.entrance.x},${plan.y+plan.entrance.y}</p><label>Name<input id="builtName" maxlength="100" value="${esc(existing?.name||template.name)}"></label><label>Walking & overlap<select id="builtMovement">${[...(existing?.collisionMask||template.collisionMask?[["mask","Keep fitted doorway / object shape"]]:[]),['footprint','Solid footprint · walk behind upper storeys'],['building','Solid building · entrance stays clear'],['base','Walk behind roof · solid base and clear entrance'],['walk','Walkable decoration'],['keep','Use the ground’s painted walking rules']].map(([id,label])=>`<option value="${id}" ${(existing?.collisionChoice||(map.autoCollision===false?'keep':template.collisionMask?'mask':'footprint'))===id?'selected':''}>${label}</option>`).join('')}</select></label>${!existing?.building?.interiorId?`<label class="check"><input id="builtInterior" type="checkbox" checked> ${storeLibrary?'Create matching store floors, linked stairs and all front doors':'Create an interior and link the entrance both ways'}</label>${storeLibrary?'<p>Creates the matching department-store floor set, with linked stairs and every front door. Lift doors are marked for stair access.</p>':''}<div ${storeLibrary?'hidden':''}><label>Interior layout<select id="builtLayout"><option value="recipe">Default furnished room · choose size below</option>${(api.interiors?.().list()||[]).map(t=>`<option value="${esc(t.id)}" ${t.id===template.interiorTemplateId?'selected':''}>${esc(t.name)} · ${t.width} × ${t.height}</option>`).join('')}</select></label><label class="check"><input id="builtFurnished" type="checkbox" checked> Furnish it using this building’s default layout</label><label>Interior floor & wallpaper<select id="builtTheme">${themes.map(t=>`<option value="${esc(t.id)}" ${t.id===theme?.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><div class="field-row"><label>Inside width<input id="builtInsideW" type="number" min="${recipe?.minW||12}" max="64" value="${Math.min(64,Math.max(recipe?.width||16,plan.w*2))}"></label><label>Inside height<input id="builtInsideH" type="number" min="${recipe?.minH||12}" max="64" value="${Math.min(64,Math.max(recipe?.height||14,plan.h*2))}"></label></div></div>`:'<p>The existing interior and its furnishings stay linked. Resize or redecorate that map separately.</p>'}<p class="hint-line">Interior objects get walking rules automatically. Add clerk, sign or story interactions with Events.</p>`,()=>{
   const create=!existing?.building?.interiorId&&$('#builtInterior').checked,exact=create&&api.interiors?.().list().find(t=>t.id===$('#builtLayout')?.value),w=create?(exact?.width||+$('#builtInsideW').value):0,h=create?(exact?.height||+$('#builtInsideH').value):0;if(create&&(!Number.isInteger(w)||!Number.isInteger(h)||w<(exact?1:recipe?.minW||12)||h<(exact?1:recipe?.minH||12)||w>64||h>64))throw Error('Use at least '+(recipe?.minW||12)+' × '+(recipe?.minH||12)+' tiles, up to64 per side.');
   const p=api.project();if(create&&(p.maps.length>=80||p.maps.reduce((n,m)=>n+m.width*m.height,0)+w*h>400000))throw Error('This interior exceeds the project map or tile limit.');if(p.assets.length>=512)throw Error('This project has reached its embedded image limit.');const a={id:uid(),name:$('#builtName').value.trim()||template.name,width:canvas.width,height:canvas.height,tileSize:16,data:canvas.toDataURL('image/png'),category:'Constructed buildings'};let interior;
   if(!existing&&map.objects.length>=5000)throw Error('This map has reached 5,000 objects.');
   api.change(()=>{p.assets.push(a);api.library.attach(p,'buildingTemplates',template);let o=buildingObject(template,plan,a.id);o.name=a.name;o.collisionChoice=$('#builtMovement').value;if(existing){Object.assign(existing,{...o,id:existing.id,building:{...existing.building,entrance:plan.entrance}});syncLinks(existing);o=existing;}else map.objects.push(o);
    if(create&&storeLibrary){const session=api.session();interior=attachDepartmentStore(p,map,o,template,plan,storeLibrary,{sourceId:session?.id||map.rom?.sourceId||null,reader:session?.reader});}else if(create&&exact){api.library.attach(p,'interiorTemplates',exact);const session=api.session();interior=linkInteriorToBuilding(p,map,o,exact,{name:a.name+' · inside',sourceId:session?.id||map.rom?.sourceId||null,templateKey:session?.reader.code===exact.sourceCode&&session.reader.byKey(exact.sourceKey)?exact.sourceKey:null});}else if(create){const roomRecipe={...recipe,themeId:$('#builtTheme').value};api.library.attach(p,'roomStyles',themes.find(t=>t.id===roomRecipe.themeId));for(const placement of roomRecipe.placements||[]){const prefab=api.smart().prefabs().find(p=>p.id===placement.id);if(prefab)api.library.attach(p,'prefabs',prefab);}interior=makeInterior(p,map,o,template,roomRecipe,{width:w,height:h,name:a.name+' · inside',decorate:$('#builtFurnished').checked,prefabs:api.smart().prefabs(),themes});if(interior.rom){const session=api.session();if(session&&recipe?.romTemplate?.code===session.reader.code&&session.reader.byKey(recipe.romTemplate.key))interior.rom.templateKey=recipe.romTemplate.key;}const link=p.links.at(-1);link.buildingId=o.id;}
   });api.refresh();api.toast(interior?'Building, furnished interior and return portal created.':'Building constructed.');
  },existing?'Update building':'Build');
  if($('#builtLayout')){const update=()=>{const exact=api.interiors?.().list().find(t=>t.id===$('#builtLayout').value);for(const [id,size]of[['builtInsideW',exact?.width],['builtInsideH',exact?.height]]){const input=$('#'+id);input.disabled=!!exact;if(exact){input.min=1;input.value=size;}else input.min=id==='builtInsideW'?(recipe?.minW||12):(recipe?.minH||12);}$('#builtTheme').disabled=!!exact;$('#builtFurnished').disabled=!!exact;};$('#builtLayout').onchange=update;update();}
 }catch(error){api.error(error);}}
 function syncLinks(o){if(o.building?.floorIds){const t=buildings().find(t=>t.id===o.building.templateId);if(t?.departmentFamily){const plan=planBuilding(t,{x1:o.x,y1:o.y,x2:o.x+o.w-1,y2:o.y+o.h-1},api.map());fitDepartmentDoors(o,t,plan,api.project().links);}}for(const l of api.project().links)if(l.buildingId===o.id){const e=l.buildingEntrance||o.building.entrance;Object.assign(l[l.buildingEnd||'from'],{x:Math.round(o.x+e.x),y:Math.round(o.y+e.y)});api.doors()?.syncArt(l);}}
 function resize(o){const t=buildings().find(t=>t.id===o.building.templateId),axes=t?buildingAxes(t):{x:false,y:false},resizable=axes.x||axes.y;api.modal(resizable?'Resize '+o.name:'Building · '+o.name,`${resizable?`<div class="field-row"><label>Width<input id="resizeBuildingW" type="number" value="${o.w}" min="${t?.w||o.w}" max="64" ${!axes.x?'disabled':''}></label><label>Height<input id="resizeBuildingH" type="number" value="${o.h}" min="${t?.h||o.h}" max="64" ${!axes.y?'disabled':''}></label></div><p>Only the enabled axes resize. The entrance follows its original door.</p>`:'<p>This building keeps its original pixel size.</p>'}<label>Name<input id="placedBuildingName" value="${esc(o.name)}" maxlength="100"></label><div class="smart-actions">${!o.building.interiorId&&t?'<button id="addBuiltInterior" type="button">Create & link an interior</button>':''}${o.building.interiorId?'<button id="visitBuiltInterior" type="button">Open linked interior</button>':''}<button id="duplicateBuiltBuilding" type="button">Duplicate building</button><button id="saveBuiltObject" type="button">Save as library object</button><button id="removeBuiltBuilding" type="button" class="danger">Delete building</button></div>`,()=>{api.change(()=>o.name=$('#placedBuildingName').value.trim()||o.name);if(!resizable){api.refresh();return;}construct({x1:o.x,y1:o.y,x2:o.x+Number($('#resizeBuildingW').value)-1,y2:o.y+Number($('#resizeBuildingH').value)-1},o);return false;},resizable?'Preview size':'Save building');if($('#addBuiltInterior'))$('#addBuiltInterior').onclick=()=>construct({x1:o.x,y1:o.y,x2:o.x+o.w-1,y2:o.y+o.h-1},o);if($('#visitBuiltInterior'))$('#visitBuiltInterior').onclick=()=>{api.close();api.openMap(o.building.interiorId);};$('#duplicateBuiltBuilding').onclick=()=>{const map=api.map();if(map.objects.length>=5000)throw Error('This map has reached its object limit.');const copy=structuredClone(o);copy.id=uid();copy.name=o.name+' copy';copy.x=Math.min(o.x+1,map.width-o.w);copy.y=Math.min(o.y+1,map.height-o.h);delete copy.building.interiorId;api.change(()=>map.objects.push(copy));api.close();api.select(copy);api.refresh();api.toast('Building copied at the same size. Add an interior from Edit.');};$('#saveBuiltObject').onclick=()=>api.smart().savePlacement(o);$('#removeBuiltBuilding').onclick=()=>{api.change(()=>{api.map().objects=api.map().objects.filter(a=>a.id!==o.id);api.project().links=api.project().links.filter(l=>l.buildingId!==o.id);});api.close();api.refresh();api.toast('Building removed. Its interior map is kept.');};}
 function paintTrees(x,y){if(state.buildingBrush){const p=buildingItems().find(p=>p.id===state.buildingBrush);if(p)paintBuildingRow(api.map(),p,x,y);return;}const selected=trees().filter(p=>state.treeIds.includes(p.id));if(!selected.length)return;const map=api.map();for(let dy=1-state.radius;dy<state.radius;dy++)for(let dx=1-state.radius;dx<state.radius;dx++){const xx=x+dx,yy=y+dy;if(dx*dx+dy*dy>=state.radius*state.radius)continue;const p=selected[Math.abs(Math.imul(xx,73856093)^Math.imul(yy,19349663))%selected.length];if(map.objects.length>=5000&&!state.erase){api.toast('This map has reached 5,000 objects.');return;}plantTree(map,p,xx,yy,{spacing:state.spacing,erase:state.erase});}}
 function placeAt(x,y,templateId){try{const t=buildings().find(t=>t.id===(templateId||state.templateId));if(!t)throw Error('Choose a building.');if(api.map().objects.length>=5000)throw Error('This map has reached its object limit.');const plan=planBuilding(t,{x1:x,y1:y,x2:x+t.w-1,y2:y+t.h-1},api.map()),o=buildingObject(t,plan,t.assetId);if(api.map().autoCollision===false)o.collisionChoice='keep';o.sx=t.sx||0;o.sy=t.sy||0;api.change(()=>{api.library.attach(api.project(),'buildingTemplates',t);api.map().objects.push(o);});api.select(o);api.refresh();api.toast('Building placed. Move → Edit to add or visit its interior.');if(state.offerInterior)construct({x1:x,y1:y,x2:x+t.w-1,y2:y+t.h-1},o);return o;}catch(e){api.error(e);}}
 return{state,open,buildings,buildingItems,trees,construct,placeAt,resize,syncLinks,paintTrees};
}
